CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, ih TEXT NOT NULL, cid TEXT, type TEXT NOT NULL, stop TEXT, to_stop TEXT, host TEXT, path TEXT, src TEXT, country TEXT, region TEXT, tz TEXT, ref TEXT, dev TEXT); CREATE INDEX IF NOT EXISTS ev_ts ON events(ts); CREATE INDEX IF NOT EXISTS ev_ih ON events(ih, ts); CREATE TABLE IF NOT EXISTS daily (day TEXT NOT NULL, stop TEXT NOT NULL, views INTEGER NOT NULL, riders INTEGER NOT NULL, PRIMARY KEY (day, stop)); CREATE TABLE IF NOT EXISTS sheets (name TEXT PRIMARY KEY, fetched INTEGER NOT NULL, data TEXT NOT NULL); CREATE TABLE IF NOT EXISTS riders (ih TEXT PRIMARY KEY, first INTEGER NOT NULL, last INTEGER); CREATE INDEX IF NOT EXISTS riders_first ON riders(first); CREATE INDEX IF NOT EXISTS riders_last ON riders(last); CREATE TABLE IF NOT EXISTS cache (k TEXT PRIMARY KEY, at INTEGER NOT NULL, data TEXT NOT NULL); CREATE TABLE IF NOT EXISTS rollup (day TEXT PRIMARY KEY, data TEXT NOT NULL); CREATE TABLE IF NOT EXISTS bots (hour TEXT NOT NULL, kind TEXT NOT NULL, name TEXT NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (hour, kind, name));
